function accept_fix(fix_case, ask) {
  const repaired = fix_case.jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = fix_case.jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  for (const n of fix_case.nearby) {
    if (n.before === n.after) continue;
    const truth = ask(n.id);
    if (truth === null) return false;
    if (n.before === truth) return false;
  }
  return true;
}
